    """Shift letters by k (wrapping), preserve case, leave other chars unchanged.
    caesar('Ab-z', 1) -> 'Bc-a'"""
    result = []
    for ch in s:
        if 'a' <= ch <= 'z':
            result.append(chr((ord(ch) - ord('a') + k) % 26 + ord('a')))
        elif 'A' <= ch <= 'Z':
            result.append(chr((ord(ch) - ord('A') + k) % 26 + ord('A')))
        else:
            result.append(ch)
    return ''.join(result)
